import os,sys
skip={"target","node_modules",".g"+"it"}
files=[]
for d,ds,fs in os.walk("."):
    ds[:]=[x for x in ds if x not in skip]
    for f in fs: files.append(os.path.join(d,f)[2:])
txt={}
for p in files:
    try: txt[p]=open(p,errors="ignore").read()
    except: pass
big="\n".join(f"@@{p}@@\n{t}" for p,t in txt.items() if not p.endswith(("Cargo.lock","CHANGELOG.md")) and not p.endswith(".snap"))
print("files",len(files))
for p in sorted(files):
    if p.endswith(("Cargo.lock","CHANGELOG.md","Cargo.toml","LICENSE")) or "/CHANGELOG" in p: continue
    b=os.path.basename(p); stem=os.path.splitext(b)[0]
    cnt=0
    for q,t in txt.items():
        if q==p: continue
        if q.endswith("CHANGELOG.md"): continue
        if b in t or (len(stem)>5 and stem in t): cnt+=1
    if cnt==0: print("NOREF",p)
EOF
