import os,re
jf=open("justfile").read().split("\n")
names=[]
for l in jf:
    m=re.match(r"^([a-z][a-z0-9_-]*)\b[^:=]*:(?!=)(.*)$",l)
    if m: names.append((m.group(1),m.group(2)))
txt={}
for d,ds,fs in os.walk("."):
    ds[:]=[x for x in ds if x not in ("target","node_modules",".moon") and not (len(x)==4 and x[:2]==".g")]
    for f in fs:
        p=os.path.join(d,f)
        try:
            txt[p]=open(p,errors="ignore").read()
        except Exception:
            pass
print(len(names),"recipes")
for n,deps in names:
    c=[]
    for p,t in txt.items():
        if "CHANGELOG" in p:
            continue
        if re.search(r"\bjust\s+(--[a-z-]+\s+)*"+re.escape(n)+r"\b",t):
            c.append(p)
    dep=[m for m,d in names if m!=n and re.search(r"(^|\s)"+re.escape(n)+r"(\s|$)",d)]
    print(n,"refs:",len(c),c[:3],"dep-of:",dep)
EOF
