import re,os
cli=open("crates/callisto-cli/src/cli.rs").read()
src={}
for r,ds,fs in os.walk("crates/callisto-cli/src"):
    for f in fs:
        if f.endswith(".rs"): src[os.path.join(r,f)]=open(os.path.join(r,f)).read()
fields=re.findall(r"#\[(?:arg|command)\([^\]]*\)\]\s*(?:#\[[^\]]*\]\s*)*pub\s+([a-z_][a-z0-9_]*)\s*:",cli)
fields+=re.findall(r"^\s+pub ([a-z_][a-z0-9_]*): ",cli,re.M)
fields=sorted(set(fields))
print(len(fields),"pub struct fields in cli.rs")
for f in fields:
    n=0
    for p,t in src.items():
        if p.endswith("cli.rs"):
            n+=len(re.findall(r"\b"+f+r"\b",t))-1 if False else 0
            # count uses other than definition: in cli.rs, count occurrences minus 1
            n+=max(0,len(re.findall(r"\bargs\."+f+r"\b|\.\b"+f+r"\b|\b"+f+r"\b:",t))-0)
        else:
            n+=len(re.findall(r"\b"+f+r"\b",t))
    # find non-cli.rs uses
    other=sum(len(re.findall(r"\b"+f+r"\b",t)) for p,t in src.items() if not p.endswith("cli.rs"))
    if other==0: print("no use outside cli.rs:",f)
EOF
